"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6530],{3366:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ActivePerksGuiController","desc":"Binds the Studio-authored `StarterGui.ActivePerksGui` to `PerkClient`: a\\nread-only view of the perks buffing the player right now. A Personal perk is\\nactive at the player\'s own level > 0; a Party perk at the server-wide max, and\\n`PerkOwner` names the player holding it. Opens from a TopbarPlus icon (toggle\\nkey O); TopbarPlus deselects other icons, so this and the Perk menu never stack.\\n`ResetPersonalPerksButton` respecs the open tab\'s pool on a hold (`HoldButton`).","realm":["Client"],"source":{"line":13,"path":"src/StarterPlayer/StarterPlayerScripts/ActivePerksGuiController.client.luau"}}')}}]);